from format_lecon import Lesson,paras,table,steps
from diagnostics import DIAGNOSTICS

def make(n):return Lesson(DIAGNOSTICS[n-1][0],n)
l=make(1)
l.add('La laryngite aiguë est une inflammation récente du larynx qui modifie la voix. Le {périmètre du diagnostic} distingue la forme simple des infections ou œdèmes menaçant les voies aériennes.',paras('Une voix enrouée dans un contexte viral peut correspondre à une inflammation des plis vocaux. Le terme ne doit pas devenir une étiquette pour tout bruit respiratoire ou toute difficulté à avaler. Une épiglottite ou une autre obstruction laryngée exige une démarche urgente distincte.', 'Une aphonie peut accompagner une inflammation importante, mais son intensité ne mesure pas à elle seule la gravité respiratoire.'),(3,6))
l.add('Les HUG décrivent une origine souvent virale. Les {contextes favorisants} comprennent infection récente et exposition irritante, sans fournir une incidence suisse utilisable pour cette entité.',paras('La consultation peut suivre une infection des voies respiratoires supérieures, une sollicitation vocale ou une irritation. Ces circonstances orientent mais ne démontrent pas l’étiologie. Les chiffres de toutes les dysphonies ne peuvent pas servir d’incidence de la laryngite aiguë.', 'Chez l’enfant, la dysphonie ou la modification du cri associée à une gêne respiratoire relève d’une évaluation pédiatrique spécifique ; le raisonnement de la forme simple de l’adulte ne suffit pas.'),(3,6))
l.add('L’inflammation épaissit la muqueuse et modifie sa souplesse. Les {conséquences vibratoires} expliquent la raucité et la fatigue sans prouver une infection bactérienne.',paras('Une muqueuse œdématiée vibre moins régulièrement. Le patient peut augmenter son effort pour maintenir la voix, ajoutant un traumatisme mécanique à l’inflammation. Réduire cet effort traite donc un mécanisme aggravant.', 'La rougeur laryngée est peu spécifique : irritation, infection et traumatisme peuvent se ressembler. Elle ne justifie pas à elle seule un antibiotique.'),(3,6,8))
l.add('Une laryngite présumée devient une urgence si elle s’accompagne de signes d’obstruction. Les {diagnostics à ne pas manquer} comprennent une atteinte supraglottique grave et une complication après geste ou traumatisme.',table(['🚩 Constat','Interprétation','Action'],[['Stridor, tirage ou gêne rapidement croissante.','La forme simple n’explique pas suffisamment la situation.','Équipe des voies aériennes en urgence.'],['Douleur importante, déglutition très difficile ou sécrétions non gérées.','Infection ou obstruction plus profonde possible.','Évaluation urgente adaptée sans retarder la sécurisation respiratoire.'],['Début après intubation ou traumatisme.','Lésion, œdème ou trouble de mobilité.','Visualisation et bilan orientés selon la stabilité.'],['Persistance ou progression chez un fumeur.','Une lésion chronique ou tumorale reste possible.','Examen ORL et révision du diagnostic initial.']]),(3,5,6,8))
l.add('L’histoire doit relier le début vocal au contexte et vérifier l’évolution. Les {éléments discriminants} empêchent de confondre épisode aigu et symptôme chronique récemment remarqué.',paras('Demander si la voix était réellement normale auparavant, si les symptômes respiratoires régressent et si la dysphonie suit la même évolution. Préciser effort vocal, exposition à la fumée, inhalations, intubation et chirurgie récente.', 'Une gêne qui continue à augmenter malgré la fin de l’épisode infectieux, une douleur inhabituelle ou un retentissement de déglutition modifient l’orientation. Chez un professionnel, documenter les contraintes de reprise sans les laisser dicter un traitement empirique risqué.'),(3,6,8))
l.add('L’examen cherche une concordance entre contexte aigu et atteinte laryngée. Les {limites du diagnostic clinique} imposent une visualisation lorsqu’un signe d’alarme ou une évolution atypique est présent.',paras('Décrire la voix et les signes associés ; une simple inspection pharyngée ne visualise pas les plis vocaux. Si une laryngoscopie est indiquée, elle peut montrer une inflammation diffuse et permet surtout de chercher lésion focale ou immobilité.', 'Une endoscopie n’est pas obligatoirement immédiate dans tout épisode bref et simple qui s’améliore. Elle ne doit cependant pas être différée par la seule présomption d’une origine virale lorsque le contexte impose un examen.'),(3,6,8))
l.add('Le syndrome attendu associe dysphonie récente et contexte inflammatoire. Les {discordances syndromiques} orientent vers une autre cause plutôt que vers une laryngite toujours plus sévère.',table(['Profil','Conséquence'],[['Raucité récente, symptômes infectieux en amélioration.','Compatible avec une forme simple, sous réserve de l’évolution.'],['Voix surtout soufflée après chirurgie.','Rechercher une insuffisance de fermeture ou une paralysie.'],['Bruit inspiratoire avec gêne respiratoire.','Traiter le syndrome obstructif.'],['Lésion focale persistante.','Caractériser la lésion ; ne pas la réduire à une inflammation diffuse.']]),(3,4,6))
l.add('Le diagnostic repose sur un ensemble clinique cohérent et une évolution favorable. Les {critères de réévaluation} évitent de le maintenir artificiellement en cas de persistance.',paras('Il n’existe pas, dans les sources retenues, de score de confirmation unique pour la laryngite aiguë simple. L’absence de signe d’alarme, le contexte et l’amélioration soutiennent l’hypothèse ; ils ne remplacent pas l’examen laryngé lorsqu’il devient indiqué.', 'Une voix durablement altérée, une lésion suspecte ou une immobilité sortent du cadre d’une simple prescription de repos. Rechercher alors la cause précise et documenter le suivi.'),(3,6,8))
l.add('Les examens ne sont pas systématiques dans une forme simple qui régresse. Les {quatre questions du bilan} précisent quand l’exploration apporte une réponse utile.',paras('9.a — Référence : appréciation clinique, complétée par la visualisation du larynx si nécessaire ; aucun prélèvement ne confirme à lui seul toutes les laryngites.', '9.b — Première intention si alarme ou évolution atypique : examen ORL adapté à la stabilité respiratoire.', '9.c — Adapter l’examen à l’âge et à la tolérance ; si une obstruction est suspectée, organiser les conditions de sécurité avec les spécialistes.', '9.d — Biologie, microbiologie et imagerie répondent à une suspicion spécifique de complication ou d’autre maladie. Ni scanner ni antibiotique ne sont automatiques devant une voix rauque.'),(3,6,8))
l.add('L’{algorithme de l’épisode aigu} distingue la forme simple d’une évolution qui nécessite un examen. La réévaluation est une étape du traitement.',steps('Alarme respiratoire ou déglutition très altérée → prise en charge urgente adaptée.', 'Forme récente sans alarme et en amélioration → mesures conservatrices, réduction de l’effort vocal et consignes.', 'Aggravation, contexte postopératoire ou doute diagnostique → examen spécialisé plus précoce.', 'Persistance → visualiser le larynx et revoir la cause, sans prolonger indéfiniment l’étiquette virale.'),(3,6,8))
l.add('La forme simple bénéficie de mesures conservatrices. Le {traitement et son suivi} évitent les prescriptions systématiques sans indication démontrée.',paras('11.A — Diminuer l’inflammation entretenue par l’effort et permettre la récupération de la voix, tout en surveillant l’évolution.', '11.B — Adapter le repos vocal, maintenir une hydratation habituelle et éviter fumée et autres irritants. Les HUG jugent les antibiotiques généralement inutiles, car la cause est souvent virale. Les corticoïdes ne sont pas un traitement empirique automatique d’une dysphonie non explorée ; une indication différente exige son propre diagnostic.', '11.C — Contrôler l’amélioration et réévaluer si la voix persiste, s’aggrave ou si un nouveau signe apparaît. Ne pas utiliser la seule baisse de douleur comme preuve de guérison laryngée.', '11.D — Prévoir une reprise vocale adaptée au métier, des consignes de recours en cas de dyspnée ou de déglutition difficile, et un suivi si l’évolution ne devient pas favorable. Aucun schéma médicamenteux n’est nécessaire à la forme simple décrite.'),(3,8))
l.add('La prévention vise les irritants et le surmenage d’un larynx déjà inflammatoire. Les {mesures successives} accompagnent l’épisode et la reprise de la voix.',paras('Primaire : limiter l’exposition à la fumée et adapter l’usage vocal aux circonstances. Secondaire : reconnaître l’aggravation ou l’absence d’amélioration et demander un nouvel examen. Tertiaire : après l’épisode, reprendre progressivement les contraintes vocales et traiter un éventuel geste de forçage persistant.'),(2,3))
l.add('Une cause virale est fréquente, mais ne se déduit pas de la seule raucité. Les signes respiratoires ou de déglutition changent la priorité. Antibiotiques et corticoïdes ne sont pas automatiques. Une évolution atypique impose de revoir le diagnostic.',refs=(3,6,8))
l.quiz([('La raucité prouve-t-elle une bactérie ?','Non : inflammation virale, irritation et traumatisme peuvent donner une raucité.'),('Une rougeur impose-t-elle un antibiotique ?','Non : elle est peu spécifique.'),('Une aphonie intense mesure-t-elle la détresse respiratoire ?','Non : les fonctions vocales et respiratoires doivent être appréciées séparément.'),('Que change un stridor ?','Il fait rechercher et prendre en charge une obstruction.'),('La gêne majeure à avaler appartient-elle toujours à la forme simple ?','Non : elle peut traduire une infection ou une obstruction plus grave.'),('Une bouche normale montre-t-elle les plis vocaux ?','Non : leur inspection demande une technique adaptée.'),('Un épisode viral explique-t-il toute persistance ?','Non : une autre lésion peut être concomitante ou découverte à cette occasion.'),('Faut-il poursuivre le forçage pour retrouver la voix ?','Non : il peut entretenir le traumatisme muqueux.'),('Le scanner est-il systématique ?','Non : il répond à une question de complication ou de diagnostic différent.'),('Une profession vocale justifie-t-elle d’emblée des corticoïdes ?','Non : l’indication doit être évaluée, sans court-circuiter l’examen nécessaire.'),('Quel contexte change le raisonnement après intubation ?','Une lésion mécanique ou une immobilité peuvent expliquer la dysphonie.'),('L’amélioration doit-elle être suivie ?','Oui : l’absence d’amélioration ou l’aggravation modifie la conduite.'),('La régression de la douleur suffit-elle ?','Non : elle ne prouve pas la normalisation du larynx ou de la voix.'),('Peut-on donner un chiffre suisse d’incidence à partir de ces sources ?','Non : elles ne fournissent pas un taux spécifique exploitable.')],(3,6,8))
l.write()

l=make(2)
l.add('La dysphonie fonctionnelle traduit un usage ou une coordination inadéquats de la voix. Les {limites de cette définition} empêchent d’assimiler fonctionnel à imaginaire ou à simplement psychologique.',paras('La plainte est réelle et peut être très handicapante sans lésion organique suffisante pour l’expliquer. Le geste vocal mobilise respiration, vibration et résonance ; sa désorganisation peut provoquer fatigue et effort.', 'Une anomalie fonctionnelle peut coexister avec une lésion, notamment après une période de compensation. Le diagnostic demande donc une appréciation positive du fonctionnement et un examen laryngé, pas seulement une absence d’anomalie à l’inspection de la bouche.'),(2,6))
l.add('Les professionnels sollicitant beaucoup leur voix constituent un contexte classique. Les {facteurs de charge} décrivent l’exposition sans établir de causalité automatique.',paras('Les HUG citent notamment enseignants et chanteurs. Durée d’utilisation, environnement bruyant et récupération insuffisante peuvent augmenter l’effort. L’impact social ou professionnel n’est pas proportionnel à une éventuelle lésion.', 'Les sources suisses retenues ne donnent pas de prévalence permettant de classer cette cause parmi toutes les dysphonies. Un métier vocal ne dispense jamais de rechercher une lésion organique ou une atteinte neurologique.'),(1,2))
l.add('Une coordination inefficace peut entraîner une compensation musculaire excessive. Les {boucles de forçage} expliquent comment effort, fatigue et dégradation vocale peuvent s’entretenir.',paras('Lorsque le souffle, la mise en vibration et la résonance sont mal coordonnés, le patient peut augmenter sa tension pour obtenir le son attendu. Cette stratégie accroît parfois la fatigue sans améliorer durablement la communication.', 'La rééducation cherche un geste plus efficient. Elle ne consiste pas seulement à parler moins : le bilan identifie les tâches, les tensions et les comportements à modifier. Une lésion associée doit être intégrée à ce raisonnement.'),(2,6))
l.add('Le diagnostic fonctionnel ne doit pas neutraliser un signe d’alarme. Les {discordances à explorer} conduisent à rechercher une cause lésionnelle ou neurologique.',table(['🚩 Discordance','Hypothèse à vérifier'],[['Persistance progressive, tabac ou lésion visible.','Lésion organique, dont cancer selon le contexte.'],['Début après chirurgie et voix soufflée.','Insuffisance glottique ou paralysie.'],['Interruptions dépendant de tâches précises.','Dystonie laryngée à distinguer du forçage.'],['Trouble respiratoire ou fausses routes.','Atteinte des autres fonctions laryngées ; reconsidérer la priorité.']]),(2,4,5,6))
l.add('L’anamnèse recherche les circonstances qui augmentent ou diminuent la difficulté. Les {questions sur l’usage vocal} servent à construire des objectifs de rééducation mesurables.',paras('Comparer parole prolongée, téléphone, cours, chant et conversation calme. Demander le moment d’apparition de la fatigue, le besoin de pousser la voix, les pauses disponibles et les stratégies de compensation. Relever les épisodes infectieux ou lésions ayant précédé le changement.', 'Explorer le retentissement et les attentes sans attribuer d’emblée la plainte au stress. Les facteurs émotionnels peuvent influencer la voix, mais ne prouvent pas une origine psychogène.'),(2,6))
l.add('L’examen phoniatrique observe la voix en situation et visualise le larynx. Les {constatations fonctionnelles} sont confrontées à l’état de la muqueuse et à la mobilité.',paras('Évaluer le souffle, l’effort perceptible, les tensions et la variabilité selon les tâches. Observer si une consigne adaptée modifie la production sonore, sans en faire un test unique de confirmation.', 'L’examen laryngé recherche lésion, défaut de fermeture et anomalie de mobilité. Une exploration de la vibration peut compléter un examen qui n’explique pas la plainte. Une vue normale trop sommaire ne suffit pas à affirmer la fonctionnalité.'),(2,6))
l.add('Le syndrome associe surtout effort, fatigue et variabilité vocale. Les {profils à différencier} évitent de confondre dysfonction du geste et trouble neurologique.',table(['Profil','Orientation'],[['Effort augmentant avec la charge, coordination inefficace.','Dysfonction vocale possible.'],['Spasmes reproductibles selon certaines tâches.','Dystonie à caractériser.'],['Souffle constant avec fermeture déficiente.','Insuffisance glottique à explorer.'],['Raucité avec lésion focale.','Composante organique à traiter aussi.']]),(2,4,6,7))
l.add('Le diagnostic repose sur la concordance entre plainte, observation fonctionnelle et examen laryngé. Les {critères de prudence} empêchent un diagnostic par défaut.',paras('Aucun score isolé ne remplace ce bilan. Décrire les anomalies du geste et vérifier qu’une lésion structurelle ou motrice ne rend pas mieux compte du trouble.', 'Une amélioration avec la rééducation soutient l’utilité de la prise en charge ; elle ne démontre pas rétrospectivement l’absence de toute autre cause. Une discordance persistante impose une nouvelle évaluation.'),(2,6,8))
l.add('Le bilan vocal spécialisé complète la visualisation du larynx. Les {examens utiles et inutiles} dépendent de la question clinique.',paras('9.a — Référence : évaluation phoniatrique clinique et examen laryngé ; pas de biomarqueur de dysphonie fonctionnelle.', '9.b — Décrire perceptivement la voix, son endurance et son retentissement ; documenter muqueuse et mobilité avant la rééducation.', '9.c — Adapter les tâches au métier et à la plainte réelle, sans se limiter à une voyelle tenue.', '9.d — Stroboscopie si anomalie vibratoire suspectée ; bilan neurologique si spasmes ou autres signes. L’imagerie n’est pas automatique devant une plainte fonctionnelle présumée.'),(2,6,8))
l.add('L’{algorithme fonctionnel} commence par établir ce qui gêne réellement la communication. Il associe traitement du geste et réévaluation des hypothèses.',steps('Visualiser le larynx et caractériser les tâches gênantes.', 'Si lésion ou atteinte motrice suffisante → traiter cette cause et les compensations associées.', 'Si dysfonction du geste concordante → proposer logopédie et adaptations de l’usage vocal.', 'Si progrès insuffisant ou nouveau signe → revoir diagnostic, objectifs, exposition et adhésion avec le patient.'),(2,6))
l.add('La logopédie constitue le traitement central d’une dysphonie fonctionnelle caractérisée. Les {composantes de la prise en charge} associent apprentissage, adaptation des contraintes et suivi.',paras('11.A — Obtenir une voix utilisable avec moins d’effort et améliorer l’endurance dans les activités importantes pour le patient.', '11.B — Les HUG décrivent un travail sur souffle, vibration et résonance. Associer hydratation habituelle, pauses adaptées et réduction des irritants. Ajuster les contraintes professionnelles ; un simple conseil de silence sans analyse du geste ne suffit pas.', '11.C — Comparer fatigue, effort et capacité de communication aux objectifs initiaux. Vérifier que les techniques sont transposables hors séance. Réexaminer une réponse insuffisante, surtout si les symptômes changent.', '11.D — Organiser un programme réalisable et une reprise professionnelle adaptée. Il n’existe pas de médicament standard remplaçant la rééducation du geste ; ne pas traiter automatiquement un reflux supposé.'),(2,8))
l.add('La prévention repose sur une utilisation de la voix compatible avec les contraintes du patient. Les {trois niveaux de prévention} renforcent l’autonomie plutôt que des interdictions universelles.',paras('Primaire : réduire les conditions qui obligent à pousser la voix et prévoir une récupération adaptée. Secondaire : consulter si la fatigue ou la dysphonie persiste. Tertiaire : maintenir les stratégies apprises, identifier les situations de rechute et réévaluer une modification du tableau.'),(2,6))
l.add('Fonctionnel ne signifie pas imaginaire. Le diagnostic exige une observation du geste et un examen laryngé. La logopédie travaille la coordination vocale. Une réponse insuffisante ou un nouveau signe doit faire réexaminer la cause.',refs=(2,6))
l.quiz([('Un enseignant dysphonique a-t-il forcément une dysphonie fonctionnelle ?','Non : son métier constitue un contexte, pas une preuve.'),('Fonctionnel signifie-t-il volontaire ?','Non : la difficulté et le handicap sont réels.'),('L’absence de lésion à l’inspection de la bouche suffit-elle ?','Non : elle ne décrit pas le larynx.'),('Pourquoi comparer différentes tâches ?','Les contraintes et les mécanismes peuvent varier entre conversation, chant et parole prolongée.'),('Le stress démontre-t-il une cause psychogène ?','Non : il peut modifier de nombreuses maladies et ne remplace pas le bilan.'),('Une lésion et un forçage peuvent-ils coexister ?','Oui : une compensation fonctionnelle peut accompagner une cause organique.'),('Quel traitement travaille souffle, vibration et résonance ?','La logopédie adaptée au bilan.'),('Parler moins suffit-il toujours ?','Non : la coordination et les conditions de travail peuvent nécessiter un apprentissage.'),('Une amélioration sous consigne est-elle un test unique ?','Non : elle s’intègre à l’ensemble du bilan.'),('Des spasmes selon la tâche suggèrent-ils une autre piste ?','Oui : une dystonie laryngée doit être distinguée du forçage.'),('Un médicament remplace-t-il la rééducation du geste ?','Non : aucun traitement médicamenteux standard ne la remplace.'),('Faut-il mesurer seulement la beauté du timbre ?','Non : effort, endurance et communication sont des objectifs essentiels.'),('Que faire si la rééducation échoue ?','Revoir le diagnostic, la stratégie, les contraintes et la possibilité d’une cause associée.'),('Une voix soufflée après chirurgie doit-elle être dite fonctionnelle ?','Non : il faut notamment rechercher une insuffisance de fermeture ou une paralysie.')],(2,4,6,8))
l.write()

l=make(3)
l.add('Les nodules vocaux sont de petites lésions bénignes liées à des traumatismes vocaux répétés. Leur {morphologie habituelle} est bilatérale, mais toute paire de lésions ne constitue pas automatiquement des nodules.',paras('Ils correspondent à une réaction de la muqueuse aux contacts répétés pendant la phonation. Le diagnostic compare les deux plis vocaux, la localisation des lésions et leur effet sur la fermeture.', 'Une lésion unilatérale peut produire une réaction sur le pli opposé. La distinction avec polype ou kyste modifie le traitement et justifie une observation spécialisée.'),(3,6))
l.add('Les sollicitations vocales répétées constituent le contexte classique. Les {limites épidémiologiques} interdisent d’en déduire une fréquence suisse chiffrée à partir de ces sources.',paras('Les HUG relient les nodules à l’utilisation abusive de la voix. Le contexte peut concerner activité professionnelle, chant ou cris répétés. Il ne permet pas de prédire à lui seul quelle lésion s’est formée.', 'Aucune incidence suisse spécifique comparable n’a été retrouvée dans les sources retenues. Le retentissement dépend des besoins vocaux et de la compensation, pas seulement du volume des nodules.'),(2,3))
l.add('Les contacts répétés provoquent un épaississement local de la muqueuse. Les {effets sur la fermeture} peuvent entretenir la fatigue et le forçage.',paras('Les deux plis ne s’accolent plus de façon optimale autour des reliefs. La vibration devient moins régulière et une fuite d’air peut accroître l’effort nécessaire pour produire la voix.', 'Une compensation plus énergique entretient parfois le mécanisme traumatique initial. La rééducation vise cette boucle, ce qui explique sa place avant une éventuelle chirurgie.'),(3,6))
l.add('Le caractère bénin ne se décide pas à partir de la seule histoire de forçage. Les {signes atypiques} doivent faire reconsidérer la nature des lésions.',table(['🚩 Constat','Conséquence'],[['Lésion irrégulière, ulcérée ou asymétrie inhabituelle.','Caractérisation spécialisée ; prélèvement si suspicion.'],['Exposition au tabac et évolution progressive.','Ne pas attribuer la persistance à des nodules sans examen adéquat.'],['Mobilité anormale.','Chercher une cause distincte ou associée.'],['Gêne respiratoire ou de déglutition importante.','Les petits nodules usuels ne suffisent pas à expliquer ce tableau.']]),(3,5,6))
l.add('L’histoire décrit les contraintes répétées et les compensations. Les {questions ciblées} préparent une intervention sur les facteurs qui entretiennent les lésions.',paras('Rechercher cris, effort en milieu bruyant, chant prolongé, fatigue en fin de journée et récupération après repos. Demander les traitements déjà entrepris, notamment une logopédie, et les raisons d’une reprise du forçage.', 'Préciser les besoins professionnels et la gêne réellement limitante. Une demande de chirurgie immédiate doit être discutée en expliquant que l’ablation ne corrige pas, à elle seule, le mécanisme vocal.'),(2,3))
l.add('La visualisation compare les deux plis et leur comportement en phonation. Les {constatations caractéristiques} doivent rester cohérentes avec la plainte.',paras('Rechercher des reliefs bilatéraux en regard, leur symétrie et l’effet sur la fermeture. Étudier la mobilité et, si nécessaire, la vibration muqueuse pour distinguer un nodule d’une lésion plus profonde.', 'L’écoute décrit raucité, souffle et fatigue, mais ne distingue pas à elle seule nodule et polype. L’examen de la voix dans les tâches habituelles complète l’image anatomique.'),(3,6))
l.add('Le syndrome combine lésion muqueuse bénigne et surcharge vocale. Les {associations possibles} expliquent pourquoi le traitement doit tenir compte du geste vocal.',table(['Composante','Signification'],[['Reliefs bilatéraux concordants.','Compatible avec des nodules.'],['Fermeture incomplète et souffle.','Retentissement mécanique possible.'],['Tension et effort compensatoires.','Cible de la logopédie.'],['Lésion profonde ou unilatérale dominante.','Rechercher notamment kyste ou polype.']]),(2,3,6))
l.add('Le diagnostic positif est laryngologique et fonctionnel. Les {critères de concordance} séparent l’aspect typique des situations incertaines.',paras('L’aspect de lésions bilatérales en regard dans un contexte compatible soutient le diagnostic. Il faut vérifier l’absence d’anomalie expliquant mieux la plainte et apprécier la vibration si nécessaire.', 'L’histologie n’est pas un préalable systématique à la prise en charge de nodules typiques traités conservativement. Elle devient pertinente lorsqu’une intervention ou une suspicion lésionnelle la justifie.'),(3,6))
l.add('L’examen laryngé et l’évaluation vocale suffisent souvent à orienter la prise en charge. Les {examens complémentaires ciblés} évitent une exploration disproportionnée.',paras('9.a — Référence : observation laryngée en phonation et interprétation spécialisée.', '9.b — Première intention : documenter morphologie, fermeture, mobilité et retentissement vocal.', '9.c — Adapter la tâche au chant ou au métier ; recourir à la stroboscopie si la vibration ou le diagnostic différentiel doit être précisé.', '9.d — Histologie si exérèse ou doute suspect ; une imagerie cervicale n’est pas systématique pour des nodules typiques.'),(3,6,8))
l.add('L’{algorithme des nodules} privilégie la correction du mécanisme traumatique. La persistance doit être interprétée avec le handicap et la qualité du diagnostic.',steps('Confirmer une morphologie compatible et exclure une lésion suspecte.', 'Analyser les contraintes et commencer une logopédie adaptée.', 'Réévaluer gêne, usage vocal et lésions.', 'Si lésions et handicap persistent malgré une prise en charge appropriée → discuter une chirurgie spécialisée et son accompagnement rééducatif.'),(2,3))
l.add('La logopédie est habituellement la première étape du traitement. Les {conditions d’une éventuelle chirurgie} dépendent de la persistance et du retentissement.',paras('11.A — Réduire l’effort et les traumatismes répétés, améliorer la communication et l’endurance.', '11.B — Les HUG proposent d’abord la logopédie, avec discussion de chirurgie si nécessaire. Travailler la technique et les situations déclenchantes ; adapter le repos et les contraintes sans promettre une disparition immédiate.', '11.C — Comparer les symptômes, le fonctionnement vocal et les constatations laryngées. Si le résultat est insuffisant, vérifier l’application des adaptations et reconsidérer le diagnostic différentiel.', '11.D — La décision d’exérèse est partagée avec le spécialiste ; la muqueuse vibrante doit être préservée et la rééducation poursuivie selon le plan. Ni antibiotique ni traitement antireflux empirique ne remplace cette stratégie.'),(2,3,8))
l.add('Prévenir la récidive demande de réduire les contraintes qui ont favorisé les nodules. Les {mesures durables} associent technique, environnement et suivi.',paras('Primaire : limiter les efforts répétés inadaptés à la situation vocale. Secondaire : consulter devant fatigue ou raucité persistante et caractériser les lésions. Tertiaire : conserver les stratégies apprises après amélioration ou chirurgie, avec contrôle en cas de retour des symptômes.'),(2,3))
l.add('Les nodules sont habituellement bilatéraux et liés à un traumatisme répété. Leur identification demande un examen du larynx. La logopédie précède souvent la chirurgie. Une présentation atypique impose de revoir le diagnostic.',refs=(2,3,6))
l.quiz([('Un nodule est-il une tumeur maligne ?','Non : le nodule vocal typique est une lésion bénigne.'),('Deux reliefs prouvent-ils toujours deux nodules ?','Non : une lésion peut entraîner une réaction de contact opposée.'),('Le forçage permet-il de nommer la lésion sans l’examiner ?','Non : polypes et autres lésions peuvent partager ce contexte.'),('Pourquoi la voix peut-elle être soufflée ?','Les reliefs peuvent perturber la fermeture glottique.'),('L’effort compensatoire peut-il entretenir le problème ?','Oui : il peut poursuivre le traumatisme mécanique.'),('Quel traitement est souvent proposé en premier ?','La logopédie adaptée aux contraintes et au geste vocal.'),('Une chirurgie corrige-t-elle automatiquement l’usage vocal ?','Non : les comportements et contraintes doivent aussi être traités.'),('Le timbre permet-il de distinguer nodule et kyste ?','Non : l’examen laryngé est nécessaire.'),('Quand étudier la vibration ?','Lorsque le diagnostic ou le retentissement vibratoire doit être précisé.'),('Faut-il biopsier tout nodule typique avant logopédie ?','Non : le prélèvement dépend du doute ou d’une intervention indiquée.'),('Une lésion ulcérée doit-elle être appelée nodule par habitude ?','Non : elle demande une caractérisation appropriée.'),('Une détresse respiratoire est-elle expliquée par de petits nodules usuels ?','Non : une autre cause doit être recherchée en urgence.'),('Qu’évaluer avant une chirurgie pour persistance ?','Le handicap, le diagnostic, la rééducation et les contraintes restantes.'),('Le suivi s’arrête-t-il dès que la voix est meilleure ?','Non : les stratégies de prévention et la conduite en cas de rechute restent utiles.')],(2,3,6,8))
l.write()
